@id("root-assets-class-id") class Assets { public Catalog Catalog = new(); }
class Catalog { public List<Row> Rows = [new Row()]; public static DerivedItem PresentOwner = Present; public static DerivedItem EmptyOwner = Empty; public static Group PresentGroup = FromPresent; public static Group EmptyGroup = FromEmpty; }
NeoLookupVariantFolder<Piece, Row> Rows = new(path: "Rows", collection: Catalog.Rows, collectionValue: Reference(root.Assets.Catalog.Rows));

DerivedItem Present = new { Placed = Piece.Variants.Seven };
DerivedItem Empty = new();
Group FromPresent = new {
        Spawns = [new Spawn {
            Variant = Present.Placed,
        }],
    };
Group FromEmpty = new {
        Spawns = [new Spawn {
            Variant = Empty.Placed,
        }],
    };

class Probe {
    @storage(allowed: .Session) private static int Receivers = 0;
    @storage(allowed: .Session) private static int Arguments = 0;
    private static Spawn Selection(bool present) { Receivers++; return new() { Variant = present ? Piece.Variants.Seven : null }; }
    private static LookupSelection Lookup(bool present) { Receivers++; return new() { Variant = present ? Piece.Variants.Rows.ByRow : null }; }
    private static Row Argument() { Arguments++; return root.Assets.Catalog.Rows[0]; }
    public static int StoredPresent() => Catalog.PresentGroup.Spawns[0].Variant!.Initialize().Rank;
    public static bool StoredNull() => Catalog.EmptyGroup.Spawns[0].Variant == null;
    public static bool ConditionalNull() { Receivers = 0; Piece? value = Selection(false).Variant?.Initialize(); return value == null && Receivers == 1; }
    public static bool ConditionalPresent() { Receivers = 0; int value = Selection(true).Variant?.Initialize().Rank ?? -1; return value == 7 && Receivers == 1; }
    public static bool LookupNullSkipsArgument() { Receivers = 0; Arguments = 0; var value = Lookup(false).Variant?.Initialize(Argument()); return value == null && Receivers == 1 && Arguments == 0; }
    public static bool LookupPresentOnce() { Receivers = 0; Arguments = 0; var value = Lookup(true).Variant?.Initialize(Argument()); return value?.Rank == 9 && Receivers == 1 && Arguments == 1; }
}
